<template><div class="page">
 <div class="page-header"><div><div class="page-title">账户异动监控</div><div class="note">每日 08:40 获取启用计费账户前一日账单，按此前最多30个有效日计算基准，并保存每日变化率。</div></div><el-button type="primary" :loading="syncing" @click="syncNow">立即同步并分析</el-button></div>
 <div class="cards"><el-card v-for="c in cards" :key="c.label" shadow="never"><div class="value" :class="c.type">{{c.value}}</div><div class="label">{{c.label}}</div></el-card></div>
 <el-tabs v-model="tab">
  <el-tab-pane label="异动排行" name="results"><el-card shadow="never"><el-form inline><el-form-item label="账单日期"><el-date-picker v-model="query.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="账户"><el-input v-model="query.keyword" clearable placeholder="名称或编号"/></el-form-item><el-form-item label="分析状态"><el-select v-model="query.status" clearable><el-option label="异常" value="ANOMALY"/><el-option label="正常" value="NORMAL"/><el-option label="观察期" value="OBSERVING"/><el-option label="无数据" value="NO_DATA"/></el-select></el-form-item><el-form-item label="方向"><el-select v-model="query.direction" clearable><el-option label="突增" value="RISE"/><el-option label="突降" value="FALL"/></el-select></el-form-item><el-button @click="search">查询</el-button></el-form>
   <el-table :data="rows" v-loading="loading" border><el-table-column type="index" label="排名" width="70"/><el-table-column prop="accountName" label="账户名称" min-width="190"/><el-table-column prop="actualAmount" label="前一日金额" width="120"><template #default="{row}">{{money(row.actualAmount)}}</template></el-table-column><el-table-column prop="baselineAverage" label="历史日均" width="115"><template #default="{row}">{{money(row.baselineAverage)}}</template></el-table-column><el-table-column prop="sampleDays" label="样本" width="75"><template #default="{row}">{{row.sampleDays}}天</template></el-table-column><el-table-column label="变化" width="110"><template #default="{row}"><span :class="row.direction==='RISE'?'rise':row.direction==='FALL'?'fall':''">{{pct(row.differencePct)}}</span></template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="statusType(row.analysisStatus)">{{statusLabel(row.analysisStatus)}}</el-tag></template></el-table-column><el-table-column label="等级" width="85"><template #default="{row}">{{row.severity==='CRITICAL'?'严重':row.severity==='WARNING'?'警告':'-'}}</template></el-table-column><el-table-column label="处理" width="120"><template #default="{row}"><el-button v-if="row.analysisStatus==='ANOMALY'" link type="primary" @click="handle(row)">{{handleLabel(row.handleStatus)}}</el-button><span v-else>-</span></template></el-table-column></el-table>
   <el-pagination class="pager" v-model:current-page="page.pageNum" v-model:page-size="page.pageSize" :total="total" :page-sizes="[20,50,100]" layout="total,sizes,prev,pager,next" @current-change="loadResults" @size-change="search"/>
  </el-card></el-tab-pane>
  <el-tab-pane label="变化率走势" name="trend"><el-card shadow="never">
   <div class="trend-toolbar"><el-select v-model="trendQuery.accountNumber" filterable remote clearable :remote-method="searchAccounts" :loading="accountLoading" placeholder="输入商户名称或账户编号" @change="loadTrend"><el-option v-for="a in accountOptions" :key="a.accountNumber" :label="a.accountName" :value="a.accountNumber"><span>{{a.accountName}}</span><small>{{a.accountNumber}}</small></el-option></el-select><el-date-picker v-model="trendQuery.range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-button type="primary" :disabled="!trendQuery.accountNumber" @click="loadTrend">查看走势</el-button></div>
   <template v-if="trendData.accountNumber"><div class="trend-head"><div><b>{{trendData.accountName}}</b><span>{{trendData.accountNumber}}</span></div><el-button type="primary" plain @click="useSuggestedThreshold">参考历史设置阈值</el-button></div>
    <div class="trend-summary"><div><span>记录天数</span><b>{{trendData.summary?.recordDays||0}}</b></div><div><span>平均变化率</span><b>{{pct(trendData.summary?.averageRate)}}</b></div><div><span>最大上涨</span><b class="rise">{{pct(trendData.summary?.maxRisePct)}}</b></div><div><span>最大下降</span><b class="fall">{{trendData.summary?.maxFallPct==null?'-':'-'+Number(trendData.summary.maxFallPct).toFixed(2)+'%'}}</b></div><div><span>参考上涨阈值</span><b>{{pct(trendData.summary?.suggestedRisePct)}}</b></div><div><span>参考下降阈值</span><b>{{trendData.summary?.suggestedFallPct==null?'-':Number(trendData.summary.suggestedFallPct).toFixed(2)+'%'}}</b></div></div>
    <AccountRateTrendChart :rows="trendData.points||[]" :rise-threshold="Number(trendData.rule?.riseThresholdPct)" :fall-threshold="Number(trendData.rule?.fallThresholdPct)"/>
    <div class="trend-help">参考阈值取所选期间上涨、下降幅度各自的第90百分位，仅作为设置建议；实际报警仍同时满足“变化率阈值”和“最低偏差金额”。</div>
   </template><el-empty v-else description="请选择商户账户查看每日变化率走势"/>
  </el-card></el-tab-pane>
  <el-tab-pane label="阈值设置" name="rules"><el-card shadow="never"><div class="toolbar"><el-input v-model="ruleKeyword" clearable placeholder="搜索账户" style="max-width:280px" @keyup.enter="loadRules"/><el-button @click="loadRules">查询</el-button><el-button type="primary" @click="editDefault">系统默认阈值</el-button></div><el-table :data="rules" border v-loading="ruleLoading"><el-table-column prop="accountName" label="账户名称" min-width="210"/><el-table-column label="监控" width="80"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="上涨阈值" width="110"><template #default="{row}">{{row.riseThresholdPct==null?'默认':row.riseThresholdPct+'%'}}</template></el-table-column><el-table-column label="下降阈值" width="110"><template #default="{row}">{{row.fallThresholdPct==null?'默认':row.fallThresholdPct+'%'}}</template></el-table-column><el-table-column label="最低偏差" width="110"><template #default="{row}">{{row.minimumDifference==null?'默认':money(row.minimumDifference)}}</template></el-table-column><el-table-column label="Webhook" width="100"><template #default="{row}">{{row.webhookEnabled?'推送':'不推送'}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="140"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="editRule(row)">设置</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
  <el-tab-pane label="运行记录" name="runs"><el-card shadow="never"><el-table :data="runs" border><el-table-column prop="triggerType" label="触发" width="130"><template #default="{row}">{{row.triggerType==='SCHEDULED_0840'?'08:40 自动':'手动'}}</template></el-table-column><el-table-column prop="targetDate" label="账单日期" width="120"/><el-table-column prop="status" label="状态" width="90"><template #default="{row}">{{row.status==='SUCCESS'?'成功':row.status==='RUNNING'?'执行中':'失败'}}</template></el-table-column><el-table-column prop="accountCount" label="账户" width="80"/><el-table-column prop="successCount" label="成功" width="80"/><el-table-column prop="failedCount" label="失败" width="80"/><el-table-column prop="anomalyCount" label="异动" width="80"/><el-table-column prop="startedAt" label="开始时间" width="180"/><el-table-column prop="errorMessage" label="结果" min-width="180"/></el-table></el-card></el-tab-pane>
 </el-tabs>
 <el-dialog v-model="ruleVisible" :title="ruleForm.accountNumber==='__DEFAULT__'?'系统默认阈值':'账户阈值设置'" width="520px"><el-form label-width="125px"><el-form-item v-if="ruleForm.accountName" label="账户">{{ruleForm.accountName}}</el-form-item><el-form-item label="参与监控"><el-switch v-model="ruleForm.enabled"/></el-form-item><el-form-item label="上涨阈值"><el-input-number v-model="ruleForm.riseThresholdPct" :min="1" :max="1000"/><span class="unit">%</span></el-form-item><el-form-item label="下降阈值"><el-input-number v-model="ruleForm.fallThresholdPct" :min="1" :max="100"/><span class="unit">%</span></el-form-item><el-form-item label="最低偏差金额"><el-input-number v-model="ruleForm.minimumDifference" :min="0" :precision="2"/><span class="unit">元</span></el-form-item><el-form-item label="Webhook推送"><el-switch v-model="ruleForm.webhookEnabled"/></el-form-item><el-form-item label="临时忽略"><el-date-picker v-model="ruleForm.ignoreRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始" end-placeholder="结束"/></el-form-item><el-form-item label="备注"><el-input v-model="ruleForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="ruleVisible=false">取消</el-button><el-button type="primary" @click="saveRule">保存</el-button></template></el-dialog>
</div></template>

<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{accountAnomalyApi}from'@/api/accountAnomaly';import AccountRateTrendChart from'@/components/AccountRateTrendChart.vue';
const localDate=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const yesterday=()=>{const d=new Date();d.setDate(d.getDate()-1);return localDate(d)};const defaultRange=()=>{const end=new Date();end.setDate(end.getDate()-1);const start=new Date(end);start.setDate(start.getDate()-89);return[localDate(start),localDate(end)]};
const tab=ref('results'),overview=ref<any>({}),rows=ref<any[]>([]),rules=ref<any[]>([]),runs=ref<any[]>([]),total=ref(0),loading=ref(false),ruleLoading=ref(false),syncing=ref(false),ruleKeyword=ref(''),ruleVisible=ref(false),accountLoading=ref(false),accountOptions=ref<any[]>([]),trendData=ref<any>({});const query=reactive({date:yesterday(),keyword:'',status:'',direction:''}),page=reactive({pageNum:1,pageSize:20}),ruleForm=reactive<any>({}),trendQuery=reactive<any>({accountNumber:'',range:defaultRange()});
const cards=computed(()=>[{label:'监控账户',value:Number(overview.value.totalCount||0)},{label:'正常',value:Number(overview.value.normalCount||0),type:'ok'},{label:'异动',value:Number(overview.value.anomalyCount||0),type:'bad'},{label:'突增',value:Number(overview.value.riseCount||0),type:'bad'},{label:'突降',value:Number(overview.value.fallCount||0),type:'warn'},{label:'观察期',value:Number(overview.value.observingCount||0),type:'muted'}]);const money=(v:any)=>v==null?'-':`${Number(v).toFixed(2)}元`;const pct=(v:any)=>v==null?'-':`${Number(v)>0?'+':''}${Number(v).toFixed(2)}%`;const statusLabel=(v:string)=>({ANOMALY:'异常',NORMAL:'正常',OBSERVING:'观察期',NO_DATA:'无数据',IGNORED:'已忽略'}as any)[v]||v;const statusType=(v:string)=>v==='ANOMALY'?'danger':v==='NORMAL'?'success':v==='OBSERVING'?'warning':'info';const handleLabel=(v:string)=>({PENDING:'待确认',CONFIRMED_ANOMALY:'确认异常',CONFIRMED_NORMAL:'正常波动',IGNORED:'已忽略',RECOVERED:'已恢复'}as any)[v]||v;
async function loadResults(){loading.value=true;try{overview.value=await accountAnomalyApi.overview(query.date);const r:any=await accountAnomalyApi.results({...page,...query});rows.value=r.records||[];total.value=Number(r.total||0)}finally{loading.value=false}}function search(){page.pageNum=1;loadResults()}async function loadRules(){ruleLoading.value=true;try{rules.value=await accountAnomalyApi.rules(ruleKeyword.value) as any}finally{ruleLoading.value=false}}async function loadRuns(){runs.value=await accountAnomalyApi.runs() as any}async function syncNow(){await ElMessageBox.confirm('将获取全部启用计费账户的历史账单并执行分析，完成后可能发送异动 Webhook，是否继续？','立即分析');syncing.value=true;try{await accountAnomalyApi.sync();ElMessage.success('同步和异动分析已完成');await Promise.all([loadResults(),loadRuns()]);if(trendQuery.accountNumber)await loadTrend()}finally{syncing.value=false}}
function editRule(row:any){Object.keys(ruleForm).forEach(k=>delete ruleForm[k]);Object.assign(ruleForm,{...row,enabled:!!row.enabled,webhookEnabled:!!row.webhookEnabled,ignoreRange:row.ignoreStartDate&&row.ignoreEndDate?[row.ignoreStartDate,row.ignoreEndDate]:[]});ruleVisible.value=true}async function editDefault(){const r:any=await accountAnomalyApi.defaultRule();editRule({...r,accountNumber:'__DEFAULT__',accountName:''})}async function saveRule(){const range=ruleForm.ignoreRange||[];await accountAnomalyApi.saveRule(ruleForm.accountNumber,{...ruleForm,ignoreStartDate:range[0]||null,ignoreEndDate:range[1]||null});ElMessage.success('阈值设置已保存');ruleVisible.value=false;await loadRules();if(trendQuery.accountNumber===ruleForm.accountNumber)await loadTrend()}async function handle(row:any){const{value}=await ElMessageBox.prompt('填写处理说明','处理异动',{inputPlaceholder:'说明核实结果',inputValidator:v=>!!v?.trim()||'请填写处理说明'});await accountAnomalyApi.handle(row.id,{status:'CONFIRMED_NORMAL',remark:value});ElMessage.success('已登记为正常波动');await loadResults()}
async function searchAccounts(keyword=''){accountLoading.value=true;try{accountOptions.value=await accountAnomalyApi.accounts(keyword) as any}finally{accountLoading.value=false}}async function loadTrend(){if(!trendQuery.accountNumber)return;const range=trendQuery.range||[];trendData.value=await accountAnomalyApi.trend({accountNumber:trendQuery.accountNumber,startDate:range[0],endDate:range[1]}) as any}function useSuggestedThreshold(){const s=trendData.value.summary||{},r=trendData.value.rule||{};if(s.suggestedRisePct==null&&s.suggestedFallPct==null){ElMessage.warning('有效历史数据不足，暂时无法生成参考阈值');return}editRule({...r,accountNumber:trendData.value.accountNumber,accountName:trendData.value.accountName,riseThresholdPct:s.suggestedRisePct??r.riseThresholdPct,fallThresholdPct:s.suggestedFallPct??r.fallThresholdPct,remark:r.remark||'根据历史变化率走势设置'})}
watch(tab,v=>{if(v==='rules')loadRules();if(v==='runs')loadRuns();if(v==='trend'&&!accountOptions.value.length)searchAccounts()});onMounted(()=>Promise.all([loadResults(),loadRuns()]));
</script>

<style scoped>.note{color:#909399;font-size:13px;margin-top:6px}.cards{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:14px 0}.cards .value{font-size:26px;font-weight:700}.cards .label{color:#909399;margin-top:5px}.ok{color:#67c23a}.bad{color:#f56c6c}.warn{color:#e6a23c}.muted{color:#909399}.rise{color:#f56c6c;font-weight:700}.fall{color:#409eff;font-weight:700}.pager{margin-top:12px;justify-content:flex-end}.toolbar,.trend-toolbar,.trend-head{display:flex;gap:10px;align-items:center}.toolbar{margin-bottom:14px}.trend-toolbar{flex-wrap:wrap;margin-bottom:18px}.trend-toolbar>.el-select{width:380px}.trend-toolbar small{float:right;color:#909399;margin-left:18px}.trend-head{justify-content:space-between;border-top:1px solid #ebeef5;padding-top:16px}.trend-head b{display:block;font-size:18px}.trend-head span{color:#909399;font-size:12px}.trend-summary{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:14px 0}.trend-summary>div{background:#f7f8fa;border-radius:7px;padding:12px}.trend-summary span{display:block;color:#909399;font-size:12px}.trend-summary b{display:block;margin-top:6px;font-size:18px}.trend-help{color:#909399;font-size:12px;line-height:1.6;margin-top:8px}.unit{margin-left:8px;color:#909399}@media(max-width:768px){.cards{grid-template-columns:repeat(2,1fr)}.page-header{align-items:flex-start;gap:8px}.el-form{display:flex;flex-direction:column}.el-form-item{margin-right:0}.toolbar{flex-wrap:wrap}.trend-toolbar{align-items:stretch;flex-direction:column}.trend-toolbar>*{width:100%!important}.trend-head{align-items:flex-start}.trend-summary{grid-template-columns:repeat(2,1fr)}:deep(.el-dialog){width:94%!important}}</style>
